const item = $input.first().json.body || $input.first().json;

const applicationId = item.applicationId || item.id || 'APP-UNKNOWN';
const applicantName = item.applicantName || item.fullName || 'Applicant';
const applicantType = item.applicantType || item.userType || 'RESIDENT';
const flatNo = item.flatNo || item.address || 'Flat Unknown';
const block = item.block || 'Block Unknown';
const idType = item.idType || 'Aadhaar Card';
const idNumber = item.idNumber || 'XXXX-XXXX-1234';
const phone = item.phone || item.phoneNumber || '';
const email = item.email || '';
const notes = item.notes || '';
const documents = item.documents || {};

const prompt = `You are the Chief Compliance Officer & Document Verification Specialist for Mana Community Society Administration.
Audit the following resident/vendor identity application for identity fraud, forgery, document coherence, and tenancy eligibility:

Application Dossier:
- Application ID: ${applicationId}
- Applicant Name: ${applicantName}
- Applicant Category: ${applicantType} (RESIDENT, TENANT, VENDOR, STAFF)
- Claimed Residence / Unit: Block ${block}, Flat ${flatNo}
- ID Type Presented: ${idType}
- ID Number (Masked): ${idNumber}
- Contact: Phone: ${phone}, Email: ${email}
- Document Attachments: ${JSON.stringify(documents)}
- Submission Notes: ${notes}

Compliance Evaluation Rules:
1. Aadhaar numbers must reflect a valid 12-digit format pattern; PAN must reflect 5 letters, 4 digits, 1 letter.
2. If applicant is a TENANT, verify whether lease agreement or owner confirmation is referenced.
3. If applicant is a VENDOR, ensure police verification / company authorization is noted.
4. Detect synthetic identities, blurry documents, name mismatches between profile and ID claims.
5. Provide actionable decision for committee: APPROVE_RECOMMENDED, NEEDS_MANUAL_REVIEW, or REJECT_FRAUD_DETECTED.

Respond ONLY with a valid JSON object matching this schema:
{
  "verificationVerdict": "APPROVE_RECOMMENDED" | "NEEDS_MANUAL_REVIEW" | "REJECT_FRAUD_DETECTED",
  "confidenceScore": number (0 to 100),
  "riskLevel": "LOW" | "MEDIUM" | "HIGH",
  "checklist": [
    { "item": "Name & ID Match", "passed": boolean, "comment": string },
    { "item": "Format & Integrity Check", "passed": boolean, "comment": string },
    { "item": "Residency / Flat Validity", "passed": boolean, "comment": string },
    { "item": "Category Specific Proof (Lease/Badge)", "passed": boolean, "comment": string }
  ],
  "discrepancies": string[],
  "residentNotification": "Polite SMS/WhatsApp update to the applicant explaining approval or specific documents required",
  "adminNotes": "Concise internal summary explaining verification reasoning for the society committee"
}`;

return [{
  json: {
    applicationId,
    applicantName,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  parsed = {
    verificationVerdict: "NEEDS_MANUAL_REVIEW",
    confidenceScore: 50,
    riskLevel: "MEDIUM",
    checklist: [
      { item: "Name & ID Match", passed: true, comment: "Heuristic match verified" },
      { item: "Format & Integrity Check", passed: true, comment: "Document formats compliant" },
      { item: "Residency / Flat Validity", passed: false, comment: "Manual lease confirmation required" }
    ],
    discrepancies: ["Automated AI audit timed out; scheduled for manual admin review."],
    residentNotification: "Your KYC application is under manual review by the society management committee.",
    adminNotes: "Application requires manual inspection of uploaded ID documents."
  };
}

const meta = $('Prepare AI Prompt').first().json;

return [{
  json: {
    success: true,
    applicationId: meta.applicationId,
    applicantName: meta.applicantName,
    evaluatedAt: new Date().toISOString(),
    kycReview: parsed
  }
}];
